-- Comprehensive 10-category benchmark calibrated for native Lua and VM sandbox execution.
-- Categories: Arithmetic, Function Calls, Recursion, Table Alloc, Array Indexing,
-- Pairs Traversal, String Operations, Closures/Upvalues, Metatables, Bitwise Simulation.

local benchmarks = {}
local function add(name, iters, fn)
    benchmarks[#benchmarks + 1] = { name = name, iters = iters, fn = fn }
end

-- 1. Arithmetic & numeric loop
add("arithmetic loop", 300, function(iters)
    local x = 0
    for i = 1, iters do
        x = (x + i * 3 - (i % 7)) % 2147483647
    end
    return x
end)

-- 2. Function calls & parameter passing
add("function calls", 250, function(iters)
    local function calc(a, b, c)
        return (a * 7 + b * 13 + c) % 65521
    end
    local s = 0
    for i = 1, iters do
        s = s + calc(i % 100, (i + 1) % 100, 3)
    end
    return s
end)

-- 3. Recursive stack frames (GCD recursion)
add("recursive calls", 100, function(iters)
    local function gcd(a, b)
        if b == 0 then return a end
        return gcd(b, a % b)
    end
    local s = 0
    for i = 1, iters do
        s = s + gcd(i * 17 + 1, (i % 31) + 1)
    end
    return s
end)

-- 4. Table allocation & field insertions
add("table allocate", 60, function(iters)
    local last
    for i = 1, iters do
        local t = { a = i, b = i * 2, c = i * 3 }
        t.d = i + 1
        last = t
    end
    return last
end)

-- 5. Sequential array indexing & accumulation
add("array processing", 150, function(iters)
    local arr = {}
    for i = 1, 100 do arr[i] = i end
    local sum = 0
    for i = 1, iters do
        local idx = (i % 100) + 1
        arr[idx] = arr[idx] + 1
        sum = (sum + arr[idx]) % 1000000
    end
    return sum
end)

-- 6. Hash map traversal via pairs()
add("pairs traversal", 10, function(iters)
    local map = {}
    for i = 1, 50 do map["k" .. i] = i end
    local sum = 0
    for _ = 1, iters do
        for k, v in pairs(map) do
            sum = sum + v
        end
    end
    return sum
end)

-- 7. String operations (substring, byte, concatenation)
add("string operations", 100, function(iters)
    local base = "pVM_Secured_Payload_Integrity_Check_2026"
    local total = 0
    for i = 1, iters do
        local s = string.sub(base, 1, (i % 20) + 5)
        total = total + string.byte(s, 1) + #s
    end
    return total
end)

-- 8. Closures & scoped upvalues
add("closures upvalues", 200, function(iters)
    local function makeCounter(start)
        local c = start
        return function(step)
            c = c + step
            return c
        end
    end
    local cnt = makeCounter(10)
    local acc = 0
    for i = 1, iters do
        acc = acc + cnt(i % 5)
    end
    return acc
end)

-- 9. Metatable __index and method resolution
add("metatable index", 80, function(iters)
    local parent = { baseVal = 777, multiplier = 3 }
    local child = setmetatable({}, { __index = parent })
    local s = 0
    for i = 1, iters do
        s = (s + child.baseVal * child.multiplier + i) % 1000000
    end
    return s
end)

-- 10. Bitwise logic & modular arithmetic simulation
add("bitwise simulation", 120, function(iters)
    local a = 21845
    local b = 43690
    local res = 0
    for i = 1, iters do
        local x = (a * 3 + i) % 65536
        local y = (b * 5 + i) % 65536
        res = (res + (x + y - (x % 256) - (y % 256))) % 65536
    end
    return res
end)

-- 11. Trigonometric & coordinate math
add("math trigonometry", 50, function(iters)
    local s = 0
    for i = 1, iters do
        local rad = (i % 360) * 0.017453292519943295
        local v = math.sin(rad) * math.cos(rad) + math.sqrt(i % 100 + 1)
        s = s + v
    end
    return s
end)

-- 12. Nested 2D matrix traversal
add("nested grid matrix", 80, function(iters)
    local acc = 0
    for i = 1, iters do
        for j = 1, 4 do
            acc = (acc + i * j) % 65521
        end
    end
    return acc
end)

-- 13. Dynamic varargs & pcall execution
add("varargs & pcall", 60, function(iters)
    local function unpackAndSum(...)
        local n = select("#", ...)
        local s = 0
        for i = 1, n do s = s + select(i, ...) end
        return s
    end
    local total = 0
    for i = 1, iters do
        local ok, val = pcall(unpackAndSum, i, i + 1, i + 2)
        if ok then total = (total + val) % 1000000 end
    end
    return total
end)

-- 14. String pattern matching & substitution
add("pattern matching", 60, function(iters)
    local src = "player_100:hp=250:mp=100:lvl=50"
    local count = 0
    for i = 1, iters do
        local replaced = string.gsub(src, "(%d+)", function(n)
            return tostring(tonumber(n) + 1)
        end)
        count = count + #replaced
    end
    return count
end)

local function run(b)
    if collectgarbage then pcall(collectgarbage) end
    local start = os.clock()
    b.fn(b.iters)
    local elapsed = os.clock() - start
    return elapsed
end

-- Column widths
local name_w = 4
local iter_w = 10
local time_w = 8

for i = 1, #benchmarks do
    local b = benchmarks[i]
    if #b.name > name_w then name_w = #b.name end
    local ilen = string.len(tostring(math.floor(b.iters)))
    if ilen > iter_w then iter_w = ilen end
end

local function pad(s, w)
    local l = #s
    if l < w then return s .. string.rep(" ", w - l) end
    return s
end

local function safePrint(...)
    print(...)
    if io and io.flush then pcall(io.flush) end
end

safePrint("pVM benchmark")
safePrint()
safePrint(pad("name", name_w) .. " " .. pad("iterations", iter_w) .. " time(s)")

local total = 0
for i = 1, #benchmarks do
    local b = benchmarks[i]
    local t = run(b)
    total = total + t
    local time_s = string.format("%.6f", t)
    if #time_s > time_w then time_w = #time_s end
    safePrint(pad(b.name, name_w) .. " " .. pad(tostring(math.floor(b.iters)), iter_w) .. " " .. time_s)
end

safePrint()
safePrint(pad("total", name_w) .. " " .. pad("", iter_w) .. " " .. string.format("%.6f", total))
`},{id:`flightController`,name:`Flight & Velocity Controller`,code:`-- Modern Roblox Flight Controller (BodyVelocity & CFrame Matrix)
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local LocalPlayer = Players.LocalPlayer
local Character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
local RootPart = Character:WaitForChild("HumanoidRootPart")
local Humanoid = Character:WaitForChild("Humanoid")

local FlightSettings = {
    Enabled = true,
    Speed = 65,
    Damping = 0.85,
    VerticalSpeed = 45,
}

local VelocityBody = Instance.new("BodyVelocity")
VelocityBody.Name = "PVM_FlightCore"
VelocityBody.MaxForce = Vector3.new(1e5, 1e5, 1e5)
VelocityBody.Velocity = Vector3.zero
VelocityBody.Parent = RootPart

local GyroBody = Instance.new("BodyGyro")
GyroBody.Name = "PVM_GyroCore"
GyroBody.MaxTorque = Vector3.new(1e5, 1e5, 1e5)
GyroBody.P = 15000
GyroBody.Parent = RootPart

RunService.RenderStepped:Connect(function()
    if not FlightSettings.Enabled or not RootPart or not Humanoid then return end
    
    local Camera = workspace.CurrentCamera
    local MoveDir = Humanoid.MoveDirection
    local FlyVelocity = Vector3.zero
    
    if MoveDir.Magnitude > 0 then
        local CamLook = Camera.CFrame.LookVector
        local CamRight = Camera.CFrame.RightVector
        FlyVelocity = (CamLook * -MoveDir.Z + CamRight * MoveDir.X).Unit * FlightSettings.Speed
    end
    
    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
        FlyVelocity = FlyVelocity + Vector3.new(0, FlightSettings.VerticalSpeed, 0)
    elseif UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
        FlyVelocity = FlyVelocity - Vector3.new(0, FlightSettings.VerticalSpeed, 0)
    end
    
    VelocityBody.Velocity = VelocityBody.Velocity:Lerp(FlyVelocity, FlightSettings.Damping)
    GyroBody.CFrame = Camera.CFrame
end)

print("[FlightController] Engine Initialized and Hooked to RenderStepped.")
`},{id:`keySystem`,name:`Key System & HWID Gate`,code:`-- Enterprise Client Authentication & Dynamic HWID Hash Gate
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")

local ClientAuth = {
    Endpoint = "https://auth.pinatgate.internal/v1/session",
    AppId = "PVM-ROBLOX-LUA51",
    SessionSalt = 0x7E3A9,
}

local function GenerateMachineFingerprint()
    local LocalPlayer = Players.LocalPlayer
    local UserId = LocalPlayer and tostring(LocalPlayer.UserId) or "0"
    local OSPlatform = (identifyexecutor and identifyexecutor()) or "StandardLuau"
    local RawToken = UserId .. ":" .. OSPlatform .. ":" .. tostring(ClientAuth.SessionSalt)
    
    local Digest = 0x811C9DC5
    for i = 1, #RawToken do
        local Byte = string.byte(RawToken, i)
        Digest = (Digest * 0x01000193) % 4294967296
        Digest = bit32 and bit32.bxor(Digest, Byte) or (Digest + Byte) % 4294967296
    end
    return string.format("HWID-%08X", Digest)
end

function ClientAuth:VerifyAccessKey(UserKey)
    assert(type(UserKey) == "string", "Invalid License Key format")
    local HWID = GenerateMachineFingerprint()
    
    print("[Auth] Contacting verification sentinel...")
    print("[Auth] Client Hardware Signature: " .. HWID)
    
    local Checksum = 0
    for i = 1, #UserKey do
        Checksum = (Checksum + string.byte(UserKey, i) * i) % 10007
    end
    
    local IsValid = Checksum > 0 and #UserKey >= 12
    if IsValid then
        print("[Auth] Access Granted. Unpacking protected script payload...")
        return true
    else
        warn("[Auth] Security Fault: Unauthorized key or signature mismatch.")
        return false
    end
end

local Verified = ClientAuth:VerifyAccessKey("PVMPRO-9982-K4X9-V1")
`},{id:`espHighlight`,name:`Player ESP & Billboard Highlights`,code:`-- Modern Player ESP & Chams Highlight Manager
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local LocalPlayer = Players.LocalPlayer
local ESP_STORAGE = {}

local ESPConfig = {
    Enabled = true,
    BoxColor = Color3.fromRGB(255, 255, 255),
    OutlineColor = Color3.fromRGB(0, 0, 0),
    FillTransparency = 0.65,
    OutlineTransparency = 0,
    ShowTeam = false,
}

local function AttachHighlight(TargetPlayer)
    if TargetPlayer == LocalPlayer then return end
    
    local function ApplyToCharacter(Character)
        if not Character then return end
        
        local Existing = Character:FindFirstChild("PVM_Highlight")
        if Existing then Existing:Destroy() end
        
        local Highlight = Instance.new("Highlight")
        Highlight.Name = "PVM_Highlight"
        Highlight.Adornee = Character
        Highlight.FillColor = ESPConfig.BoxColor
        Highlight.OutlineColor = ESPConfig.OutlineColor
        Highlight.FillTransparency = ESPConfig.FillTransparency
        Highlight.OutlineTransparency = ESPConfig.OutlineTransparency
        Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        Highlight.Parent = Character
        
        ESP_STORAGE[TargetPlayer] = Highlight
    end
    
    TargetPlayer.CharacterAdded:Connect(ApplyToCharacter)
    if TargetPlayer.Character then
        ApplyToCharacter(TargetPlayer.Character)
    end
end

for _, Player in ipairs(Players:GetPlayers()) do
    AttachHighlight(Player)
end

Players.PlayerAdded:Connect(AttachHighlight)
Players.PlayerRemoving:Connect(function(LeavingPlayer)
    if ESP_STORAGE[LeavingPlayer] then
        ESP_STORAGE[LeavingPlayer]:Destroy()
        ESP_STORAGE[LeavingPlayer] = nil
    end
end)

print("[ESP Engine] Active. Chams rendered for all current entities.")
`},{id:`antiHookSentinel`,name:`Anti-Hook & Metamethod Sentinel`,code:`-- Metamethod Tamper Detection & Environment Sentinel
local function DeploySentinel()
    local ProtectedEnv = {
        print = print,
        warn = warn,
        pcall = pcall,
        setmetatable = setmetatable,
        getmetatable = getmetatable,
        type = type,
        rawget = rawget,
        rawset = rawset,
    }
    
    local StateIntegrity = 0xDEADBEEF
    local HookDetected = false
    
    -- Metamethod probe & tamper verification
    local CanaryTable = setmetatable({}, {
        __namecall = function(self, ...)
            StateIntegrity = StateIntegrity + 1
            return "PVM_VALID_CALL"
        end,
        __index = function(self, key)
            if key == "SecuritySignature" then
                return 0x50564D
            end
            return rawget(self, key)
        end
    })
    
    local Ok, Result = pcall(function()
        return CanaryTable:ValidateCall()
    end)
    
    if not Ok or Result ~= "PVM_VALID_CALL" then
        HookDetected = true
    end
    
    -- Verify function identity against hook signatures
    if debug and debug.info then
        local Info = debug.info(ProtectedEnv.print, "s")
        if Info and Info ~= "[C]" then
            HookDetected = true
        end
    end
    
    if HookDetected then
        warn("[Sentinel] Critical: Tampered environment detected. Disengaging execution.")
        return false
    end
    
    print("[Sentinel] Integrity verified. Environment clean and unhooked.")
    return true
