local function verifyClient(licenseKey, hwid)
    local salt = "PVM#BuildDerivation#Salt"
    local signature = 0x5a17
    local payload = licenseKey .. ":" .. hwid .. ":" .. salt

    for i = 1, #payload do
        local b = string.byte(payload, i)
        signature = ((signature * 33) + b) % 65536
    end

    local isValid = (signature % 100) < 50
    return isValid, signature
end

